// Supabase REST returns a JSON array. Depending on n8n version that arrives
// either as one item holding the array, or already split. Handle both.
const out = [];
for (const item of $input.all()) {
  const rows = Array.isArray(item.json) ? item.json : [item.json];
  for (const r of rows) {
    if (r && r.document_name) out.push({ json: r });
  }
}
if (out.length === 0) {
  throw new Error('Watchlist is empty. Did you run agent/schema.sql?');
}
return out;

// ---------------------------------------------------------------------------
// The judgment step. This is what separates an agent from a cron job.
//
// eCFR marks every section version as substantive: true | false. A typo fix,
// a cross-reference renumbering and a nomenclature change are all recorded as
// amendments, but none of them change what is legally controlled.
//
// Re-embedding 4,394 chunks because BIS corrected a comma costs money, burns
// API quota, and — worse — churns the vector store underneath answers that
// were already correct. So we split three ways:
//
//   no_change          nothing newer than what we hold
//   editorial_skipped  newer, but nothing substantive -> record and move on
//   ingest             substantive change -> re-ingest and assess blast radius
// ---------------------------------------------------------------------------
const out = [];
const responses = $input.all();
const registry  = $('Fan Out Watchlist').all();

for (let i = 0; i < responses.length; i++) {
  const reg = registry[i].json;
  const versions = responses[i].json.content_versions || [];

  const allDates = versions.map(v => v.amendment_date).filter(Boolean).sort();
  const latest   = allDates.length ? allDates[allDates.length - 1] : null;
  const held     = reg.last_ingested_amendment || null;

  const isNewer = !!latest && (!held || latest > held);

  // Everything amended after the copy we hold.
  const moved = versions.filter(v =>
    v.amendment_date && (!held || v.amendment_date > held) && !v.removed
  );
  const substantive = moved.filter(v => v.substantive);

  // Clause ids we will use to compute blast radius against past answers.
  const changedClauses = [...new Set(substantive.map(v => v.identifier).filter(Boolean))];

  let decision = 'no_change';
  if (isNewer && substantive.length > 0) decision = 'ingest';
  else if (isNewer) decision = 'editorial_skipped';

  out.push({ json: {
    document_name:  reg.document_name,
    jurisdiction:   reg.jurisdiction,
    cfr_title:      reg.cfr_title,
    cfr_part:       reg.cfr_part,
    cfr_appendix:   reg.cfr_appendix || null,   // e.g. "Supplement No. 4 to Part 744"
    source_url:     reg.source_url,
    chunks_before:  reg.chunk_count || 0,
    expected_min:   reg.expected_chunk_min,
    expected_max:   reg.expected_chunk_max,

    held_amendment:   held,
    latest_amendment: latest,
    decision,

    sections_moved:      moved.length,
    sections_substantive: substantive.length,
    changed_clauses:      changedClauses,
    changed_section_names: substantive.slice(0, 40).map(v => v.name),
  }});
}
return out;

// ---------------------------------------------------------------------------
// Parse the eCFR XML and chunk it.
//
// The chunking here deliberately mirrors ingest.js exactly — same cleaning,
// same clause-boundary split, same 512-char ceiling, same 100-char overlap.
// If the agent chunked differently from the original ingest, the vector space
// would drift and retrieval quality would quietly degrade on re-ingested
// documents only. Consistency between ingest paths is a correctness property,
// not a style preference.
//
// Emits one item per batch of 100 chunks, because Gemini's
// batchEmbedContents accepts 100 requests per call. That takes Part 774 from
// ~73 minutes at 1 req/sec down to well under a minute.
// ---------------------------------------------------------------------------
const BATCH_SIZE = 100;
const MAX_LEN    = 512;
const OVERLAP    = 100;

function xmlToText(xml) {
  return xml
    .replace(/<\?xml[^>]*\?>/g, ' ')
    .replace(/<!--[\s\S]*?-->/g, ' ')
    .replace(/<[^>]+>/g, ' ')          // drop tags, keep the text between them
    .replace(/&#x([0-9A-Fa-f]+);/g, (_, h) => String.fromCodePoint(parseInt(h, 16)))
    .replace(/&#(\d+);/g,           (_, d) => String.fromCodePoint(parseInt(d, 10)))
    .replace(/&quot;/g, '"').replace(/&amp;/g, '&')
    .replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&nbsp;/g, ' ');
}

function cleanText(text) {
  return text
    .replace(/-+Page \(\d+\) Break-+/gi, '')
    .replace(/-{3,}/g, '')
    .replace(/_{5,}/g, '')
    .replace(/\n[ \t]*\n([ \t]*\n)+/g, '\n\n')
    .trim();
}

function chunkText(text, jurisdiction) {
  text = cleanText(text).replace(/\s+/g, ' ');

  const scometRegex = /(\d[A-Z]\d{3}[a-z]?\.)/;
  const earRegex    = /([0-9][A-Z][0-9]{3}\.[a-z]\.[0-9]+)/;
  const regex = jurisdiction === 'SCOMET_INDIA' ? scometRegex
              : jurisdiction === 'EAR_US'       ? earRegex
              : new RegExp('(' + scometRegex.source + '|' + earRegex.source + ')');

  const parts = text.split(new RegExp('(?=' + regex.source + ')', 'g'));

  const chunks = [];
  let current = '';
  for (const raw of parts) {
    const part = raw.trim();
    if (!part) continue;
    if (current.length < 100) current += (current ? ' ' : '') + part;
    else { chunks.push(current); current = part; }
  }
  if (current) {
    if (current.length < 100 && chunks.length > 0) chunks[chunks.length - 1] += ' ' + current;
    else chunks.push(current);
  }

  const final = [];
  for (const chunk of chunks) {
    if (chunk.length <= MAX_LEN) { final.push(chunk); continue; }
    let start = 0;
    while (start < chunk.length) {
      let end = Math.min(start + MAX_LEN, chunk.length);
      if (end < chunk.length) {
        const lastSpace = chunk.lastIndexOf(' ', end);
        if (lastSpace > start + OVERLAP) end = lastSpace;
      }
      final.push(chunk.substring(start, end).trim());
      if (end === chunk.length) break;
      start = Math.max(0, end - OVERLAP);
    }
  }
  return final.filter(c => c.length > 0);
}

const out = [];
const docs = $('Substantive Change?').all();   // the DELETE before us returns {}

for (let i = 0; i < $input.all().length; i++) {
  const meta = docs[i].json;
  const xml  = typeof $input.all()[i].json.data === 'string'
    ? $input.all()[i].json.data
    : String($input.all()[i].json.data ?? '');

  const chunks = chunkText(xmlToText(xml), meta.jurisdiction);

  // Derive clause id / category the same way ingest.js does.
  let currentSection = 'General';
  const rows = chunks.map(chunk => {
    const scometMatch = chunk.match(/^(\d[A-Z]\d{3}[a-z]?\.)/);
    const earMatch    = chunk.match(/^([0-9][A-Z][0-9]{3}\.[a-z]\.[0-9]+)/);
    const clause_id   = scometMatch ? scometMatch[1] : (earMatch ? earMatch[1] : null);
    const category    = clause_id ? 'Category ' + clause_id.charAt(0) : 'Unknown';
    const header      = chunk.match(/^[A-Z\s]{10,}/);
    if (header) currentSection = header[0].trim();
    return {
      document_name: meta.document_name,
      jurisdiction:  meta.jurisdiction,
      category,
      section:       currentSection,
      clause_id,
      content:       chunk,
      metadata: {
        date_updated:    meta.latest_amendment,
        amendment_date:  meta.latest_amendment,   // the atomic-swap marker
        source_url:      meta.source_url,
        ingested_by:     'corpus-sentinel',
      },
    };
  });

  const total = rows.length;
  const withinBand = total >= meta.expected_min && total <= meta.expected_max;

  // ---- ROUTING -----------------------------------------------------------
  // n8n Cloud cannot sustain large volumes of vector inserts. Measured:
  //   91 chunks    completed end to end
  //   2,097 chunks stalled after 18 inserts, then again after 0
  //
  // So the agent decides, before doing any expensive work, whether this job
  // is its own size. If not it records a delegation and reports, rather than
  // starting something it cannot finish and leaving a half-written corpus.
  //
  // 300 is empirical, and editable right here in the n8n UI without a
  // re-import. Raise it if n8n proves more reliable; lower it if a run stalls.
  const INLINE_MAX = 300;

  if (total > INLINE_MAX) {
    // ONE item, not one per batch — otherwise a 3,779-chunk document would
    // write 38 identical delegation rows.
    out.push({ json: {
      ...meta,
      chunks_produced: total,
      within_band: withinBand,
      delegate: true,
      route_reason: 'Produces ' + total + ' chunks, above the ' + INLINE_MAX +
        '-chunk inline limit. n8n Cloud stalls on sustained vector inserts, so this is handed to the worker (agent/backfill.mjs --pending).',
      rows: undefined,
    }});
    continue;
  }

  for (let b = 0; b < rows.length; b += BATCH_SIZE) {
    out.push({ json: {
      ...meta,
      batch_index: Math.floor(b / BATCH_SIZE),
      batch_total: Math.ceil(rows.length / BATCH_SIZE),
      chunks_produced: total,
      within_band: withinBand,
      delegate: false,
      route_reason: 'Produces ' + total + ' chunks, within the ' + INLINE_MAX + '-chunk inline limit. Ingested by n8n directly.',
      rows: rows.slice(b, b + BATCH_SIZE),
    }});
  }
}

if (out.length === 0) throw new Error('Parsed 0 chunks — refusing to touch the corpus.');
return out;

// Shape each batch into a Gemini batchEmbedContents payload.
// outputDimensionality MUST stay 768 — it has to match both the existing
// corpus and the vector(768) column, or every future similarity score is
// meaningless.
return $input.all().map(item => ({
  json: {
    ...item.json,
    _payload: {
      requests: item.json.rows.map(r => ({
        model: 'models/gemini-embedding-001',
        content: { parts: [{ text: r.content }] },
        outputDimensionality: 768,
      })),
    },
  },
}));

// Zip embeddings back onto their chunks, then hand Supabase a ready payload.
const out = [];
const responses = $input.all();
const batches   = $('Build Embedding Request').all();

for (let i = 0; i < responses.length; i++) {
  const batch = batches[i].json;
  const embeddings = responses[i].json.embeddings || [];

  if (embeddings.length !== batch.rows.length) {
    throw new Error(
      'Embedding count mismatch on batch ' + batch.batch_index +
      ': expected ' + batch.rows.length + ', got ' + embeddings.length
    );
  }

  const rows = batch.rows.map((r, idx) => ({ ...r, embedding: embeddings[idx].values }));

  // Embed 100 at a time (efficient), but INSERT 25 at a time.
  //
  // A 768-float embedding is ~10KB of JSON, so 100 rows is a 1.5MB POST.
  // Supabase absorbs that in ~3.7s when tested directly, but n8n Cloud
  // pushing 1.5MB repeatedly over its own egress path hit a 504 "upstream
  // request timeout" after eight minutes with nothing committed. 25 rows is
  // ~390KB — small enough that a single request is never the slow thing.
  //
  // The two batch sizes solve different problems and should not be the same
  // number: the embed batch is about API quota, the insert batch is about
  // payload size.
  const INSERT_BATCH = 25;
  for (let s = 0; s < rows.length; s += INSERT_BATCH) {
    out.push({ json: { ...batch, rows: undefined, payload: rows.slice(s, s + INSERT_BATCH) } });
  }
}
return out;

// Run Once for All Items. Collapse the per-batch fan-out back to one item per
// document so the verification and swap steps run exactly once.
const byDoc = {};
for (const item of $('Assemble Rows').all()) {
  const j = item.json;
  if (!byDoc[j.document_name]) {
    byDoc[j.document_name] = { ...j, payload: undefined, batches_written: 0, chunks_written: 0 };
  }
  byDoc[j.document_name].batches_written += 1;
  byDoc[j.document_name].chunks_written  += (j.payload ? j.payload.length : 0);
}
return Object.values(byDoc).map(json => ({ json }));

// ---------------------------------------------------------------------------
// The safety gate.
//
// New rows are already in the table, tagged with the new amendment_date. The
// old rows are still there too — the corpus was never empty for a moment.
// Only if the new set is the size we expected do we delete the old set.
//
// If the parse silently regressed (eCFR changes their XML shape, a regex stops
// matching), chunks_written lands outside the expected band, we halt, and the
// previous good corpus is still serving traffic.
// ---------------------------------------------------------------------------
const out = [];
for (let i = 0; i < $input.all().length; i++) {
  const counted = $input.all()[i].json;
  const doc = $('Aggregate By Document').all()[i].json;

  // Supabase returns the exact count in the content-range header; the count
  // query below returns [{ count: n }].
  const verified = Array.isArray(counted) ? (counted[0]?.count ?? 0)
                 : (counted.count ?? doc.chunks_written);

  const within = doc.chunks_written >= doc.expected_min &&
                 doc.chunks_written <= doc.expected_max;
  const matches = Number(verified) === Number(doc.chunks_written);

  out.push({ json: {
    ...doc,
    chunks_verified: Number(verified),
    validation_passed: within && matches,
    validation_note: within
      ? (matches ? 'Chunk count within expected band and matches rows written.'
                 : 'Row count in database does not match rows written — possible partial insert.')
      : 'Chunk count ' + doc.chunks_written + ' outside expected band ' +
        doc.expected_min + '-' + doc.expected_max + '. Halting before delete.',
  }});
}
return out;

parameters.text:
=You are the regulatory-change analyst for Glosilex, an export-control compliance copilot for the India-US semiconductor corridor.

A monitored US regulation has just been re-ingested into the retrieval corpus.

Document: {{ $('Verify Before Swap').item.json.document_name }}
CFR cite: 15 CFR Part {{ $('Verify Before Swap').item.json.cfr_part }}
Version we previously held: {{ $('Verify Before Swap').item.json.held_amendment }}
Version now published: {{ $('Verify Before Swap').item.json.latest_amendment }}
Sections amended since our copy: {{ $('Verify Before Swap').item.json.sections_moved }}
Of those, marked substantive by eCFR: {{ $('Verify Before Swap').item.json.sections_substantive }}
Chunks now in corpus: {{ $('Verify Before Swap').item.json.chunks_verified }} (was {{ $('Verify Before Swap').item.json.chunks_before }})
Validation passed: {{ $('Verify Before Swap').item.json.validation_passed }}

Section titles that changed substantively:
{{ JSON.stringify($('Verify Before Swap').item.json.changed_section_names) }}

Clause identifiers that changed:
{{ JSON.stringify($('Verify Before Swap').item.json.changed_clauses) }}

Do two things.

1. Use the "past_classifications" tool to look up which previously issued Glosilex classifications cited any of the changed clause identifiers. Pass them as a single comma-separated string with no brackets and no quotes, for example: 736.2,774.1,3A001

2. Return ONLY a JSON object, no prose and no markdown fence, in this shape:

{
  "severity": "editorial" | "material" | "critical",
  "summary": "two or three sentences a compliance officer can read in ten seconds - what changed and in which sections",
  "impact": "what this means for exporters in the India-US semiconductor corridor specifically; name the ECCNs or control categories affected if you can determine them",
  "affected": [ { "classification_id": "...", "product": "...", "clause": "...", "why_it_matters": "..." } ]
}

Grade severity like this:
- "critical" if a control threshold, an ECCN scope, a license requirement or a country scope changed in a way that could flip a past determination from uncontrolled to controlled.
- "material" if the substance changed but is unlikely to flip an existing determination.
- "editorial" if on inspection the changes are nomenclature or cross-references only.

Be specific and be honest. If you cannot tell from the section titles alone, say so in "impact" rather than inventing a conclusion. An overstated alert in a compliance product costs the user real money in unnecessary legal review; an understated one costs them a violation.

