// Final audit row + registry update payloads.
const out = [];
for (const item of $input.all()) {
  const j = item.json;
  let analysis = {};
  try {
    const raw = j.output ?? j.text ?? '';
    const match = String(raw).match(/\{[\s\S]*\}/);
    if (match) analysis = JSON.parse(match[0]);
  } catch (e) {
    analysis = { severity: 'material', summary: 'Agent returned unparseable output.', impact: String(j.output ?? '').slice(0, 2000) };
  }

  const doc = $('Verify Before Swap').all()[out.length].json;   // per-item, not .first()

  out.push({ json: {
    run: {
      document_name:      doc.document_name,
      jurisdiction:       doc.jurisdiction,
      outcome:            doc.validation_passed ? 'ingested' : 'halted_validation',
      previous_amendment: doc.held_amendment,
      new_amendment:      doc.latest_amendment,
      chunks_before:      doc.chunks_before,
      chunks_after:       doc.chunks_verified,
      change_summary:     analysis.summary  ?? null,
      impact_assessment:  analysis.impact   ?? null,
      severity:           analysis.severity ?? 'material',
      affected_classifications: analysis.affected ?? null,
    },
    registry: {
      last_ingested_amendment: doc.latest_amendment,
      last_ingested_at:        new Date().toISOString(),
      chunk_count:             doc.chunks_verified,
    },
    document_name: doc.document_name,
    validation_passed: doc.validation_passed,
  }});
}
return out;

// One audit row per document that needed no work. Cheap, and it means the
// run history answers "was the corpus checked today?" not just
// "did it change today?".
return $input.all().map(item => ({ json: {
  document_name:      item.json.document_name,
  jurisdiction:       item.json.jurisdiction,
  outcome:            item.json.decision,
  previous_amendment: item.json.held_amendment,
  new_amendment:      item.json.latest_amendment,
  chunks_before:      item.json.chunks_before,
  chunks_after:       item.json.chunks_before,
  severity:           item.json.decision === 'no_change' ? 'none' : 'editorial',
  change_summary:     item.json.decision === 'no_change'
    ? 'No amendment newer than the held copy.'
    : item.json.sections_moved + ' section(s) amended, none marked substantive by eCFR. Re-ingest skipped.',
}}));
